using RoguePrince.CheatMenu;using MotherBase.EntityFramework;using UnityEngine;
internal static class PracticeTests
{
 private static void Eq<T>(T actual,T expected){if(!Equals(actual,expected))throw new Exception($"Expected {expected}, got {actual}");}
 private static void Refuse(Action action){try{action();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}throw new Exception("Unsafe request accepted");}
 private sealed class Fixture
 {
  internal GameSession Game;internal SceneActions Scenes;internal BossPhaseActions Phases;internal BossPracticeActions Practice;internal Entity Boss;internal BossComponentBase Component;internal string Kind;
  internal Fixture(string kind="Altan")
  {
   UnityEngine.Object.All.Clear();NativePhase.Calls=0;NativePhase.Advance=true;NativePhase.ThrowAfterDamage=false;DebugService.Ready=true;Application.isFocused=true;Time.timeScale=1;Time.realtimeSinceStartup=0;RunTools.RunId=1;SceneActions.flow=new();SceneActions.level=new();Game=new();SceneActions.map=new(){room=new()};Game.Player.Add(new RoomStateComponent{currentRoom=SceneActions.map.room});Scenes=new();Phases=new(Game,Scenes);Kind=kind;Spawn();Phases.Refresh();Practice=new(Game,Scenes,Phases);
  }
  internal void Spawn()
  {
   Boss=new Entity{context=Game.Player.context};Boss.Add(new MobComponent());Boss.Add(new Damageable());Boss.Add(new RoomStateComponent{currentRoom=SceneActions.map.room});Boss.Add(new AIStateComponent());Boss.Add(new MotherBase.ActionFramework.Actor());Boss.Add(new AffectableComponent());
   Component=Kind switch{"Altan"=>new AltanBossComponent(),"Baatar"=>new BaatarBossComponent(),"Berude"=>new GoatBossComponent(),"CorruptedNogai"=>new CorruptedNogaiBossComponent(),"Kaali"=>new KaaliBossComponent(),_=>new NogaiBossComponent()};
   TestBrain brain=Kind switch{"Altan"=>new AltanBossBrain(),"Baatar"=>new BaatarBossBrain(),"Berude"=>new GoatBossBrain(),"CorruptedNogai"=>new CorruptedNogaiBrain(),"Kaali"=>new KaaliBossBrain(),_=>new NogaiBossBrain()};Boss.Add(Component);Boss.Add(new BSAIInput{brain=brain});NativePhase.OriginalBoss=Boss;
  }
  internal void Start(int target=3)=>Practice.Start(Phases.Entries[0],target,()=>{});
  internal void Current(int target=3,Action release=null)
  {
   Practice.StartCurrent(Phases.Entries[0],target,release??(()=>{}));
  }
  internal void Loaded(bool rebind=false)
  {
   Boss.destroyed=true;Boss.gameObject.activeInHierarchy=false;SceneActions.level=new();Scenes.Busy=false;SceneActions.flow.isLoading=false;
   if(rebind){Game.Player=new Entity();Game.Player.Add(new RoomStateComponent{currentRoom=SceneActions.map.room});Game.Generation++;}
   Game.Ready=true;Spawn();
  }
  internal void Tick(int times=1){for(int i=0;i<times;i++){Time.realtimeSinceStartup+=.3f;Phases.Tick();Practice.Tick();}}
 }
 internal static void Run(Action<string,Action> check)
 {
  foreach(var kind in new[]{"Altan","Baatar","Berude","CorruptedNogai","Kaali","Nogai"})foreach(var target in new[]{1,2,3})check($"rebuild and select {kind} phase {target}",()=>{var f=new Fixture(kind);f.Start(target);Eq(f.Scenes.LoadCalls,1);Eq(NativePhase.Calls,0);f.Loaded();f.Tick(12);Eq(f.Practice.Busy,false);Eq(f.Practice.Error,false);Eq(f.Component.currentPhaseIndex,target);Eq(NativePhase.Calls,target-1);});
  check("rebuild enables returning from final phase to first",()=>{var f=new Fixture();f.Component.currentPhaseIndex=3;f.Start(1);f.Loaded();f.Tick(5);Eq(f.Component.currentPhaseIndex,1);Eq(NativePhase.Calls,0);Eq(f.Practice.Error,false);});
  check("missing new map cannot bind old boss",()=>{var f=new Fixture();f.Start();f.Scenes.Busy=false;SceneActions.flow.isLoading=false;f.Tick(5);Eq(f.Practice.Busy,true);Eq(NativePhase.Calls,0);Time.realtimeSinceStartup=121;f.Tick();Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);});
  check("loading accepts the expected replacement player",()=>{var f=new Fixture();f.Start();Eq(f.Practice.AwaitingReload,true);f.Game.Ready=false;f.Tick();Eq(f.Practice.Busy,true);f.Loaded(true);f.Tick(12);Eq(f.Practice.Error,false);Eq(NativePhase.Calls,2);});
  check("after binding replacement player cancels without damage",()=>{var f=new Fixture();f.Start();f.Loaded();f.Tick();f.Game.Generation++;f.Tick(6);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);});
  check("duplicate requests and unsupported target phases refuse reload",()=>{var f=new Fixture();foreach(var p in new[]{0,4,-1})Refuse(()=>f.Start(p));Eq(f.Scenes.LoadCalls,0);f.Start();Refuse(()=>f.Start());Eq(f.Scenes.LoadCalls,1);});
  check("focus loss cancels loading and never dispatches",()=>{var f=new Fixture();f.Start();Application.isFocused=false;f.Tick();f.Loaded();Application.isFocused=true;f.Tick(10);Eq(f.Practice.Busy,false);Eq(NativePhase.Calls,0);});
  check("seed run flow or destination drift cancels",()=>{foreach(var change in new Action[]{()=>SceneActions.flow.seed++,()=>RunTools.RunId++,()=>SceneActions.flow=new(),()=>{SceneActions.flow.state.guid="other";SceneActions.flow.isLoading=false;}}){var f=new Fixture();f.Start();change();f.Tick();Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);}});
  check("duplicate fresh bosses never receive phase damage",()=>{var f=new Fixture();f.Start();f.Loaded();f.Spawn();f.Tick(6);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);});
  check("wrong boss kind never receives phase damage",()=>{var f=new Fixture();f.Start();f.Loaded();f.Boss.destroyed=true;f.Kind="Nogai";f.Spawn();f.Tick(6);Eq(NativePhase.Calls,0);Time.realtimeSinceStartup=121;f.Tick();Eq(f.Practice.Error,true);});
  check("transition action blocks both further damage and success",()=>{var f=new Fixture();f.Start(2);f.Loaded();f.Tick(2);Eq(NativePhase.Calls,1);f.Boss.GetComponent<MotherBase.ActionFramework.Actor>().Transition=true;f.Tick(5);Eq(f.Practice.Busy,true);Eq(NativePhase.Calls,1);f.Boss.GetComponent<MotherBase.ActionFramework.Actor>().Transition=false;f.Tick(3);Eq(f.Practice.Error,false);Eq(f.Practice.Busy,false);});
  check("invincible transition effect prevents dispatch",()=>{var f=new Fixture();f.Start();f.Loaded();f.Boss.GetComponent<AffectableComponent>().Invincible=true;f.Tick(8);Eq(NativePhase.Calls,0);Eq(f.Practice.Busy,true);});
  check("pending threshold and opening index wait without damage",()=>{foreach(var phase in new[]{0,1}){var f=new Fixture();f.Start();f.Loaded();f.Component.currentPhaseIndex=phase;f.Component.reachedPhaseThreshold=true;f.Tick(8);Eq(NativePhase.Calls,0);Eq(f.Practice.Busy,true);}});
  check("HP decrease without phase change times out and never repeats",()=>{var f=new Fixture();f.Start();f.Loaded();NativePhase.Advance=false;f.Tick(6);Eq(NativePhase.Calls,1);Time.realtimeSinceStartup=35;f.Tick();Eq(f.Practice.Error,true);Eq(NativePhase.Calls,1);});
  check("native throw after damage stays observable without retry",()=>{var f=new Fixture();f.Start(2);f.Loaded();NativePhase.ThrowAfterDamage=true;f.Tick(3);Eq(NativePhase.Calls,1);Eq(f.Practice.Busy,true);f.Component.currentPhaseIndex=2;NativePhase.ThrowAfterDamage=false;f.Tick(4);Eq(f.Practice.Error,false);Eq(NativePhase.Calls,1);});
  check("cancel never reverses native load or damage",()=>{var f=new Fixture();f.Start();f.Loaded();NativePhase.Advance=false;f.Tick(3);Eq(NativePhase.Calls,1);f.Practice.Cancel();f.Tick(5);Eq(f.Practice.Busy,false);Eq(f.Phases.Busy,false);Eq(NativePhase.Calls,1);Eq(f.Boss.GetComponent<Damageable>().currentHealth,66f);});
  check("dead player or boss after binding cancels",()=>{foreach(var player in new[]{true,false}){var f=new Fixture();f.Start();f.Loaded();f.Tick();if(player)f.Game.Ready=false;else f.Boss.GetComponent<Damageable>().isAlive=false;f.Tick(5);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);}});
  check("new level after binding cancels the exact owner",()=>{var f=new Fixture();f.Start();f.Loaded();f.Tick();SceneActions.level=new();f.Tick(5);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);});
  check("target index overshoot is not reported as successful",()=>{var f=new Fixture();f.Start(2);f.Loaded();f.Tick();f.Component.currentPhaseIndex=3;f.Tick(5);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);});
  check("reload exception never causes duplicate load",()=>{var f=new Fixture();f.Scenes.ThrowAfterLoad=true;f.Start(1);Eq(f.Practice.Busy,true);f.Loaded();f.Tick(6);Eq(f.Scenes.LoadCalls,1);Eq(f.Practice.Error,false);});
  void Restore(BossPracticeActions a,bool rebind){var method=typeof(BossPracticeActions).GetMethod("Restore",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);if(method==null)throw new Exception("Practice cleanup entry missing");method.Invoke(a,new object[]{rebind});}
  check("expected loading rebind preserves practice ownership",()=>{var f=new Fixture();f.Start();Restore(f.Practice,true);Eq(f.Practice.Busy,true);f.Loaded(true);f.Tick(12);Eq(f.Practice.Error,false);});
  check("manual cleanup cancels pending native reload observation",()=>{var f=new Fixture();f.Start();Restore(f.Practice,false);f.Loaded();f.Tick(10);Eq(f.Practice.Busy,false);Eq(NativePhase.Calls,0);});
  check("rebind after new boss bound cancels automation",()=>{var f=new Fixture();f.Start();f.Loaded();f.Tick();Restore(f.Practice,true);f.Tick(10);Eq(f.Practice.Busy,false);Eq(NativePhase.Calls,0);});
  check("reported scene failure never dispatches",()=>{var f=new Fixture();f.Start();f.Loaded();f.Scenes.Error=true;f.Tick(5);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);});
  check("missing actor effect or transition asset cannot advance",()=>{for(int part=0;part<3;part++){var f=new Fixture();f.Start();f.Loaded();if(part==0)f.Boss.components.Remove(typeof(MotherBase.ActionFramework.Actor));else if(part==1)f.Boss.components.Remove(typeof(AffectableComponent));else f.Boss.GetComponent<BSAIInput>().brain.startPhaseAction=null;f.Tick(8);Eq(NativePhase.Calls,0);Eq(f.Practice.Busy,true);}});
  check("native context pause blocks automatic damage and resets stable window",()=>{var f=new Fixture();f.Start(2);f.Loaded();f.Tick();f.Boss.context.Paused=true;f.Tick(5);Eq(Time.timeScale,1f);Eq(NativePhase.Calls,0);Eq(f.Practice.Busy,true);f.Boss.context.Paused=false;f.Tick();Eq(NativePhase.Calls,0);f.Tick();Eq(NativePhase.Calls,1);f.Tick(4);Eq(f.Practice.Error,false);});
  check("native context pause blocks target phase success",()=>{var f=new Fixture();f.Start(1);f.Loaded();f.Boss.context.Paused=true;f.Tick(5);Eq(f.Practice.Busy,true);Eq(NativePhase.Calls,0);f.Boss.context.Paused=false;f.Tick();Eq(f.Practice.Busy,true);f.Tick();Eq(f.Practice.Busy,false);Eq(f.Practice.Error,false);});
  check("direct phase request refuses paused native context",()=>{var f=new Fixture();f.Boss.context.Paused=true;Refuse(()=>f.Phases.Request(f.Phases.Entries[0],()=>{}));Eq(NativePhase.Calls,0);Eq(f.Phases.Busy,false);});
  check("final dispatch validation refuses context paused during release",()=>{var f=new Fixture();Refuse(()=>f.Phases.Request(f.Phases.Entries[0],()=>f.Boss.context.Paused=true));Eq(NativePhase.Calls,0);Eq(f.Phases.Busy,false);});
  check("practice start refuses paused native context before reload",()=>{var f=new Fixture();f.Boss.context.Paused=true;Refuse(()=>f.Start());Eq(f.Scenes.LoadCalls,0);Eq(f.Practice.Busy,false);});
  foreach(var kind in new[]{"Altan","Baatar","Berude","CorruptedNogai","Kaali","Nogai"})foreach(var target in new[]{1,2,3})check($"current {kind} reaches phase {target} without replacing boss or arena",()=>{var f=new Fixture(kind);var boss=f.Boss.Pointer;var level=SceneActions.level.Pointer;f.Current(target);Eq(f.Practice.AwaitingReload,false);f.Tick(12);Eq(f.Practice.Busy,false);Eq(f.Practice.Error,false);Eq(f.Component.currentPhaseIndex,target);Eq(NativePhase.Calls,target-1);Eq(f.Scenes.LoadCalls,0);Eq(f.Boss.Pointer,boss);Eq(SceneActions.level.Pointer,level);});
  check("current final phase accepts only its existing target",()=>{var f=new Fixture();f.Component.currentPhaseIndex=3;foreach(var p in new[]{1,2,0,4})Refuse(()=>f.Current(p));Eq(f.Practice.Busy,false);f.Current(3);f.Tick(3);Eq(f.Practice.Error,false);Eq(NativePhase.Calls,0);Eq(f.Scenes.LoadCalls,0);});
  check("current second phase advances once and refuses reverse",()=>{var f=new Fixture();f.Component.currentPhaseIndex=2;Refuse(()=>f.Current(1));f.Current(3);f.Tick(8);Eq(f.Practice.Error,false);Eq(NativePhase.Calls,1);Eq(f.Scenes.LoadCalls,0);});
  check("current start rejects unready or paused owners before menu release",()=>{for(int part=0;part<6;part++){var f=new Fixture();if(part==0)f.Component.currentPhaseIndex=0;else if(part==1)f.Component.brainInitDone=false;else if(part==2)f.Boss.context.Paused=true;else if(part==3)f.Boss.GetComponent<Damageable>().isAlive=false;else if(part==4)f.Game.Ready=false;else Application.isFocused=false;var released=0;Refuse(()=>f.Current(3,()=>released++));Eq(released,0);Eq(f.Practice.Busy,false);Eq(f.Scenes.LoadCalls,0);Eq(NativePhase.Calls,0);}});
  check("current validates owner and phase again after releasing menu",()=>{foreach(var change in new Action<Fixture>[] {f=>SceneActions.level=new(),f=>f.Game.Generation++,f=>f.Component.currentPhaseIndex=2,f=>f.Boss.context.Paused=true,f=>Application.isFocused=false,f=>SceneActions.flow.isLoading=true,f=>Time.timeScale=0}){var f=new Fixture();Refuse(()=>f.Current(3,()=>change(f)));Eq(f.Practice.Busy,false);Eq(NativePhase.Calls,0);Eq(f.Scenes.LoadCalls,0);}});
  check("current duplicate and rebuilding requests share exclusive automation",()=>{var f=new Fixture();f.Current();Refuse(()=>f.Current());Refuse(()=>f.Start());Eq(f.Scenes.LoadCalls,0);f.Practice.Cancel();f.Start();Refuse(()=>f.Current());Eq(f.Scenes.LoadCalls,1);});
  check("current waits for transition before next damage and final success",()=>{var f=new Fixture();f.Current();f.Tick(2);Eq(NativePhase.Calls,1);f.Boss.GetComponent<MotherBase.ActionFramework.Actor>().Transition=true;f.Tick(6);Eq(NativePhase.Calls,1);Eq(f.Practice.Busy,true);f.Boss.GetComponent<MotherBase.ActionFramework.Actor>().Transition=false;f.Tick();Eq(NativePhase.Calls,1);f.Tick();Eq(NativePhase.Calls,2);f.Boss.GetComponent<AffectableComponent>().Invincible=true;f.Tick(5);Eq(f.Practice.Busy,true);f.Boss.GetComponent<AffectableComponent>().Invincible=false;f.Tick(3);Eq(f.Practice.Error,false);Eq(f.Practice.Busy,false);Eq(f.Scenes.LoadCalls,0);});
  check("current native pause resets stability before second dispatch",()=>{var f=new Fixture();f.Current();f.Tick(2);Eq(NativePhase.Calls,1);f.Boss.context.Paused=true;f.Tick(6);Eq(NativePhase.Calls,1);Eq(f.Practice.Busy,true);f.Boss.context.Paused=false;f.Tick();Eq(NativePhase.Calls,1);f.Tick();Eq(NativePhase.Calls,2);});
  check("current cancels on scene room player brain or boss identity drift",()=>{foreach(var change in new Action<Fixture>[] {f=>SceneActions.level=new(),f=>f.Game.Generation++,f=>f.Game.Player.GetComponent<RoomStateComponent>().currentRoom=new(),f=>f.Boss.GetComponent<BSAIInput>().brain=new AltanBossBrain(),f=>f.Boss.destroyed=true,f=>SceneActions.flow=new(),f=>RunTools.RunId++,f=>SceneActions.flow.seed++}){var f=new Fixture();f.Current();change(f);f.Tick(6);Eq(f.Practice.Busy,false);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);Eq(f.Scenes.LoadCalls,0);}});
  check("current loading after binding cancels instead of acquiring a replacement",()=>{var f=new Fixture();f.Current();SceneActions.flow.isLoading=true;f.Tick();f.Loaded(true);f.Tick(10);Eq(f.Practice.Busy,false);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);Eq(f.Scenes.LoadCalls,0);});
  check("current HP change without phase confirmation dispatches only once",()=>{var f=new Fixture();NativePhase.Advance=false;f.Current();f.Tick(5);Eq(NativePhase.Calls,1);Time.realtimeSinceStartup=35;f.Tick();f.Tick(4);Eq(f.Practice.Busy,false);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,1);Eq(f.Scenes.LoadCalls,0);});
  check("current uncertain native callback is observed without resubmission",()=>{var f=new Fixture();NativePhase.ThrowAfterDamage=true;f.Current(2);f.Tick(5);Eq(NativePhase.Calls,1);Eq(f.Practice.Busy,true);NativePhase.ThrowAfterDamage=false;f.Component.currentPhaseIndex=2;f.Tick(4);Eq(f.Practice.Error,false);Eq(NativePhase.Calls,1);Eq(f.Scenes.LoadCalls,0);});
  check("current focus loss or death ends automation without another damage",()=>{foreach(var change in new Action<Fixture>[] {f=>Application.isFocused=false,f=>f.Game.Ready=false,f=>f.Boss.GetComponent<Damageable>().isAlive=false}){var f=new Fixture();NativePhase.Advance=false;f.Current();f.Tick(2);Eq(NativePhase.Calls,1);change(f);f.Tick(5);Eq(f.Practice.Busy,false);Eq(f.Practice.Error,true);Eq(f.Phases.Busy,false);Eq(NativePhase.Calls,1);}});
  check("current cancellation preserves completed native damage",()=>{var f=new Fixture();f.Current();f.Tick(2);f.Practice.Cancel();var hp=f.Boss.GetComponent<Damageable>().currentHealth;f.Tick(6);Eq(f.Practice.Busy,false);Eq(NativePhase.Calls,1);Eq(f.Component.currentPhaseIndex,2);Eq(f.Boss.GetComponent<Damageable>().currentHealth,hp);Eq(f.Scenes.LoadCalls,0);});
  check("current rebind cleanup cancels immediately without reload exemption",()=>{var f=new Fixture();f.Current();Eq(f.Practice.AwaitingReload,false);Restore(f.Practice,true);f.Tick(6);Eq(f.Practice.Busy,false);Eq(NativePhase.Calls,0);Eq(f.Scenes.LoadCalls,0);});
  check("current invalid native threshold stops without dispatch",()=>{var f=new Fixture();f.Boss.GetComponent<BSAIInput>().brain.lifeRatioPhase1=0;f.Current();f.Tick(5);Eq(f.Practice.Busy,false);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);Eq(f.Scenes.LoadCalls,0);});
  check("current unexpected phase jump never confirms requested chain",()=>{var f=new Fixture();NativePhase.Advance=false;f.Current(3);f.Tick(2);Eq(NativePhase.Calls,1);f.Component.currentPhaseIndex=3;f.Tick(4);Eq(f.Practice.Error,true);Eq(f.Practice.Busy,false);Eq(NativePhase.Calls,1);});
  check("current missing transition readiness eventually times out without damage",()=>{var f=new Fixture();f.Boss.components.Remove(typeof(MotherBase.ActionFramework.Actor));f.Current();f.Tick(6);Eq(f.Practice.Busy,true);Time.realtimeSinceStartup=121;f.Tick();Eq(f.Practice.Busy,false);Eq(f.Practice.Error,true);Eq(NativePhase.Calls,0);Eq(f.Scenes.LoadCalls,0);});
  check("unbound rebuild end reports its own origin instead of previous bound identity",()=>{var f=new Fixture();f.Current(1);f.Tick(3);f.Loaded();f.Phases.Refresh();var boss=f.Boss.Pointer.ToInt64();var level=SceneActions.level.Pointer.ToInt64();f.Start(1);f.Practice.Cancel();var line=Plugin.Logs.Last(x=>x.StartsWith("boss_practice_end "));var fields=line.Split(' ').Skip(1).Select(x=>x.Split('=',2)).ToDictionary(x=>x[0],x=>x[1]);Eq(fields["bound"],"False");Eq(fields["boss"],"0");Eq(fields["level"],"0");Eq(fields["originBoss"],boss.ToString());Eq(fields["originLevel"],level.ToString());});
 }
}
